from datetime import date, timedelta


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    # Check that days is an int (not bool or any other type)
    if not isinstance(days, int) or isinstance(days, bool):
        raise TypeError

    # Convert holidays to a set for faster lookup
    holidays_set = set(holidays)

    def is_working_day(d):
        # Monday = 0, Sunday = 6; working days are 0-4 (Mon-Fri)
        return d.weekday() < 5 and d not in holidays_set

    if days == 0:
        # Return start if it's a working day, else first working day after start
        if is_working_day(start):
            return start
        else:
            d = start + timedelta(days=1)
            while not is_working_day(d):
                d += timedelta(days=1)
            return d
    elif days > 0:
        # Find the days-th working day after start (not counting start)
        count = 0
        d = start + timedelta(days=1)
        while True:
            if is_working_day(d):
                count += 1
                if count == days:
                    return d
            d += timedelta(days=1)
    else:  # days < 0
        # Find the -days-th working day before start (not counting start)
        count = 0
        d = start - timedelta(days=1)
        while True:
            if is_working_day(d):
                count += 1
                if count == -days:
                    return d
            d -= timedelta(days=1)


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    if first > last:
        return -count_workdays(last, first, holidays)

    # Convert holidays to a set for faster lookup
    holidays_set = set(holidays)

    def is_working_day(d):
        # Monday = 0, Sunday = 6; working days are 0-4 (Mon-Fri)
        return d.weekday() < 5 and d not in holidays_set

    count = 0
    d = first
    while d <= last:
        if is_working_day(d):
            count += 1
        d += timedelta(days=1)

    return count
